package com.exe201.rrms.controller;
import com.exe201.rrms.entity.*;import com.exe201.rrms.repository.*;import com.exe201.rrms.service.AuthService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/community") public class ReviewReportController {private final AuthService auth;private final ReviewRepository reviews;private final ReportRepository reports;public ReviewReportController(AuthService a,ReviewRepository r,ReportRepository p){auth=a;reviews=r;reports=p;} @PostMapping("/reviews") public Review review(HttpServletRequest req,@RequestBody Review r){r.setId(null);r.setUserId(auth.current(req).getId());return reviews.save(r);} @GetMapping("/properties/{propertyId}/reviews") public List<Review>reviews(@PathVariable Long propertyId){return reviews.findByPropertyIdAndStatusOrderByCreatedAtDesc(propertyId,"VISIBLE");} @PostMapping("/reports") public Report report(HttpServletRequest req,@RequestBody Report x){x.setId(null);x.setReporterId(auth.current(req).getId());return reports.save(x);} }
